            .json_body(&serde_json::json!({"key": "value"}))
            .unwrap();
        assert_eq!(req.method, "POST");
        assert!(req.body.is_some());
        let body: serde_json::Value = serde_json::from_slice(&req.body.unwrap()).unwrap();
