fn convert_resposta<T: serde::Serialize>(resposta: Resposta<T>) -> RespostaJson {
    RespostaJson {
        id: resposta.id.to_string(),
        ok: resposta.ok,
        status: u32::from(resposta.status),
        mensagem: resposta.mensagem,
        dados: resposta
            .dados
            .into_iter()
            .map(|d| serde_json::to_value(d).unwrap_or(serde_json::Value::Null))
            .collect(),
        erros: resposta
            .erros
            .into_iter()
            .map(|e| serde_json::to_value(e).unwrap_or(serde_json::Value::Null))
            .collect(),
    }
}

fn convert_download_resposta(resposta: Resposta<DownloadItem>) -> RespostaJson {
    let engine = base64::engine::general_purpose::STANDARD;
    RespostaJson {
        id: resposta.id.to_string(),
        ok: resposta.ok,
        status: u32::from(resposta.status),
        mensagem: resposta.mensagem,
        dados: resposta
            .dados
            .into_iter()
            .map(|d| {
                serde_json::json!({
                    "filename": d.filename,
                    "buffer": engine.encode(&d.buffer),
                    "formato": d.formato,
                })
            })
            .collect(),
        erros: resposta
            .erros
            .into_iter()
            .map(|e| serde_json::to_value(e).unwrap_or(serde_json::Value::Null))
            .collect(),
    }
}

