//! Contrato de bytes das datas: serialização, Display e parsers das APIs externas.
//!
//! Este teste fixa o formato exato consumido/emitido pelos sistemas SINIR,
//! MTR-PE e SIGOR. Trocar a biblioteca de datas não pode mudar um único byte.

use chrono::{DateTime, NaiveDate, NaiveDateTime, Utc};
use open_mtr_core::openmtr::domain::{DataMtr, FiltroMtr, Periodo, TimestampMs};

fn date(y: i32, m: u32, d: u32) -> NaiveDate {
    NaiveDate::from_ymd_opt(y, m, d).expect("data válida")
}

#[test]
fn data_mtr_serializes_dd_mm_yyyy() {
    let d = DataMtr(date(2026, 3, 7));
    assert_eq!(serde_json::to_string(&d).unwrap(), "\"07-03-2026\"");
    assert_eq!(d.to_string(), "07-03-2026");
    // Round-trip e rejeição de formatos fora do contrato.
    assert_eq!(serde_json::from_str::<DataMtr>("\"07-03-2026\"").unwrap(), d);
    assert!(serde_json::from_str::<DataMtr>("\"2026-03-07\"").is_err());
}

#[test]
fn timestamp_ms_and_periodo_serialize_iso() {
    let ts = TimestampMs(1_780_000_000_000);
    assert_eq!(serde_json::to_string(&ts).unwrap(), "1780000000000");
    let p = Periodo {
        inicio: DataMtr(date(2026, 6, 1)),
        fim: DataMtr(date(2026, 8, 10)),
    };
    assert_eq!(
        serde_json::to_string(&p).unwrap(),
        r#"{"dataInicial":"01-06-2026","dataFinal":"10-08-2026"}"#
    );
    // A leitura aceita ISO
    let iso: Periodo = serde_json::from_str(r#"{"dataInicial":"2026-06-01","dataFinal":"2026-08-10"}"#).unwrap();
    assert_eq!(iso, p);
}

#[test]
fn filtro_com_dias_e_resolvido_pelo_relogio() {
    let json = r#"{"periodo":{"dias":7},"tamanho":5}"#;
    let f: FiltroMtr = serde_json::from_str(json).unwrap();
    let p = f.periodo.expect("período");
    assert_eq!(p.fim, DataMtr(Utc::now().date_naive()));
    assert_eq!(p.inicio, DataMtr(Utc::now().date_naive() - chrono::Duration::days(7)));
}

#[test]
fn naive_datetimes_keep_iso_form() {
    let dt = date(2026, 6, 1).and_hms_opt(13, 45, 7).unwrap();
    let s = serde_json::to_string(&dt).unwrap();
    assert_eq!(s, "\"2026-06-01T13:45:07\"");
    let utc: DateTime<Utc> = DateTime::from_timestamp(1_780_000_000, 0).unwrap();
    assert_eq!(serde_json::to_string(&utc).unwrap(), "\"2026-05-28T20:26:40Z\"");
    let _ = NaiveDateTime::parse_from_str("2026-06-01T13:45:07", "%Y-%m-%dT%H:%M:%S").unwrap();
}
