pub trait Clock: Send + Sync {
    /// Instante atual em UTC.
    fn now(&self) -> DateTime<Utc>;

    /// Data civil (sem fuso) derivada de [`Clock::now`]; usada como `today()` do contexto.
    fn today(&self) -> NaiveDate {
        self.now().date_naive()
